// lyrel agent-hook opencode bridge — generated by lyrel, do not edit.
// OpenCode @opencode/cli 2.0.32: this entrypoint runs in the local TUI only.
import { Plugin } from "@opencode/plugin/tui"
import { createEffect } from "solid-js"
import { spawn, spawnSync } from "node:child_process"
import { createServer } from "node:net"
import { createHmac, randomBytes, randomUUID, timingSafeEqual } from "node:crypto"
import { mkdtempSync, mkdirSync, chmodSync, writeFileSync, rmSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"

const EXE = __EXE__

const BRIDGE_VERSION = 2
function bridgeMac(key, domain, parts) {
  const mac = createHmac("sha256", key)
  mac.update("lyrel-opencode-bridge-v2\0")
  mac.update(domain)
  mac.update(Buffer.from([0]))
  for (const part of parts) {
    const bytes = Buffer.from(part, "utf8")
    const length = Buffer.alloc(8)
    length.writeBigUInt64BE(BigInt(bytes.length))
    mac.update(length)
    mac.update(bytes)
  }
  return mac.digest()
}
function validProof(key, domain, parts, proof) {
  if (typeof proof !== "string" || !/^[a-fA-F0-9]{64}$/.test(proof)) return false
  return timingSafeEqual(bridgeMac(key, domain, parts), Buffer.from(proof, "hex"))
}

function connectionArgs() {
  const args = []
  for (let i = 0; i < process.argv.length; i++) {
    const arg = process.argv[i]
    if (arg === "--standalone") args.push(arg)
    if (arg === "--server" || arg.startsWith("--server=")) {
      const value = arg === "--server" ? process.argv[++i] : arg.slice(9)
      const url = new URL(value)
      if (url.username || url.password || url.search || url.hash) {
        throw new Error("lyrel: server URL contains credentials or private parameters; connection context not exported")
      }
      args.push("--server", url.href)
    }
  }
  return args
}

function report(presence, session_scope) {
  const { promise, resolve, reject } = Promise.withResolvers()
  const child = spawn(EXE, ["agent-hook", "opencode", "tool-complete"], {
    stdio: ["pipe", "ignore", "ignore"], windowsHide: true,
  })
  const timer = setTimeout(() => {
    child.kill()
    reject(new Error("lyrel: presence report timed out"))
  }, 10000)
  child.once("error", (error) => { clearTimeout(timer); reject(error) })
  child.once("close", (code) => {
    clearTimeout(timer)
    code === 0 ? resolve() : reject(new Error("lyrel: presence report failed"))
  })
  child.stdin.on("error", reject)
  child.stdin.end(JSON.stringify({ opencode_presence: presence, session_scope }))
  return promise
}

export default Plugin.define({
  id: "lyrel",
  setup(context) {
    if (!process.env.LYREL) return
    if (!context.ui?.router?.current || !context.ui?.tabs?.list || !context.data?.listen) {
      throw new Error("lyrel: this OpenCode TUI does not expose the required route/tabs/data interface")
    }
    const connection_argv = connectionArgs()
    let closed = false
    const client_id = randomUUID()
    const pane = process.env.LYREL_PANE
    if (!pane) throw new Error("lyrel: OpenCode TUI has no pane identity")
    const token = randomBytes(32)
    const root = process.platform === "win32" ? join(process.env.LOCALAPPDATA ?? "", "lyrel", "opencode-clients") : tmpdir()
    if (process.platform === "win32" && !process.env.LOCALAPPDATA) throw new Error("lyrel: private Windows runtime root unavailable")
    mkdirSync(root, { recursive: true })
    const directory = mkdtempSync(join(root, "lyrel-opencode-"))
    if (process.platform !== "win32") chmodSync(directory, 0o700)
    else {
      // 继承的 PSModulePath 可能指向不兼容的 Security 模块；直接使用系统 .NET ACL API。
      // 文件 owner 来自创建进程的 token，不继承目录 owner；提升权限时可能默认为 Administrators。
      // 先以 CreateNew 创建空文件并绑定当前用户，再写入 token；只改 owner，保留目录继承的 DACL。
      const script = "$ErrorActionPreference='Stop'; $p=$env:LYREL_OPENCODE_PRIVATE_DIR; $sid=[Security.Principal.WindowsIdentity]::GetCurrent().User; $system=[Security.Principal.SecurityIdentifier]::new('S-1-5-18'); $acl=[Security.AccessControl.DirectorySecurity]::new(); $acl.SetOwner($sid); $acl.SetAccessRuleProtection($true,$false); foreach($identity in @($sid,$system)) { $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($identity,'FullControl','ContainerInherit,ObjectInherit','None','Allow')) }; [IO.Directory]::SetAccessControl($p,$acl); $file=[IO.Path]::Combine($p,'client.json'); [IO.File]::Open($file,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None).Dispose(); $fileAcl=[IO.File]::GetAccessControl($file); $fileAcl.SetOwner($sid); [IO.File]::SetAccessControl($file,$fileAcl)"
      try {
        const secured = spawnSync(join(process.env.SystemRoot, "System32", "WindowsPowerShell", "v1.0", "powershell.exe"), ["-NoProfile", "-NonInteractive", "-Command", script], {
          env: { ...process.env, LYREL_OPENCODE_PRIVATE_DIR: directory }, stdio: "ignore", windowsHide: true, timeout: 10000,
        })
        if (secured.status !== 0) throw new Error("lyrel: cannot protect private client registration DACL")
      } catch {
        rmSync(directory, { recursive: true, force: true })
        throw new Error("lyrel: cannot protect private client registration DACL")
      }
    }
    const registration = join(directory, "client.json")
    const sockets = new Set()
    const pendingAuthentication = new Set()
    let activeOperations = 0
    let bridge
    let session_scope
    const identity = (info) => {
      const urls = [...new Set(info.urls)].sort()
      for (const value of urls) {
        const url = new URL(value)
        if (url.username || url.password || url.search || url.hash) throw new Error("private server URL cannot be exported")
      }
      return { pid: info.pid, urls }
    }
    const metadata = (info) => ({ id: info.id, parentID: info.parentID, fork: info.fork,
      projectID: info.projectID, title: info.title, location: info.location, time: info.time, model: info.model,
      cost: info.cost, tokens: info.tokens })
    const listener = createServer((socket) => {
      if (closed) { socket.destroy(); return }
      // Pending peers cannot consume authenticated operation slots. Evict the
      // oldest pending handshake rather than refusing every new legitimate peer.
      if (pendingAuthentication.size >= 64) {
        const oldest = pendingAuthentication.values().next().value
        pendingAuthentication.delete(oldest)
        oldest.destroy()
      }
      pendingAuthentication.add(socket)
      sockets.add(socket)
      let phase = "hello"
      let transcript
      let requestPayload
      let operationTimer
      const authenticationDeadline = performance.now() + 2000
      const authenticationTimer = setTimeout(() => socket.destroy(), 2000)
      socket.once("close", () => {
        clearTimeout(authenticationTimer)
        clearTimeout(operationTimer)
        pendingAuthentication.delete(socket)
        sockets.delete(socket)
      })
      socket.on("error", () => socket.destroy())
      let bytes = Buffer.alloc(0)
      const receive = async (chunk) => {
        if (socket.destroyed || performance.now() >= authenticationDeadline) { socket.destroy(); return }
        bytes = Buffer.concat([bytes, chunk])
        if (bytes.length > (phase === "hello" ? 4096 : 131072)) { socket.destroy(); return }
        const end = bytes.indexOf(10)
        if (end < 0) return
        if (end !== bytes.length - 1) { socket.destroy(); return }
        let frame
        try { frame = JSON.parse(bytes.subarray(0, end).toString()) } catch { socket.destroy(); return }
        bytes = Buffer.alloc(0)
        if (!frame || typeof frame !== "object" || Array.isArray(frame) || frame.version !== BRIDGE_VERSION) { socket.destroy(); return }
        if (phase === "hello") {
          if (frame.client_id !== client_id || frame.pane !== pane || typeof frame.client_nonce !== "string" || !/^[a-fA-F0-9]{64}$/.test(frame.client_nonce)) { socket.destroy(); return }
          const server_nonce = randomBytes(32).toString("hex")
          transcript = [frame.client_nonce, server_nonce, client_id, pane]
          socket.write(JSON.stringify({ version: BRIDGE_VERSION, server_nonce,
            proof: bridgeMac(token, "server-challenge", transcript).toString("hex") }) + "\n")
          phase = "request"
          return
        }
        socket.off("data", receive)
        requestPayload = frame.payload
        if (typeof requestPayload !== "string" || Buffer.byteLength(requestPayload) > 65536 || !validProof(token, "request", [...transcript, requestPayload], frame.proof)) { socket.destroy(); return }
        let request
        try { request = JSON.parse(requestPayload) } catch { socket.destroy(); return }
        if (!request || typeof request !== "object" || Array.isArray(request) || request.client_id !== client_id || request.pane !== pane) { socket.destroy(); return }
        if (performance.now() >= authenticationDeadline) { socket.destroy(); return }
        clearTimeout(authenticationTimer)
        pendingAuthentication.delete(socket)
        const reply = (value) => {
          const payload = JSON.stringify({ ...value, client_id, pane })
          const response = JSON.stringify({ version: BRIDGE_VERSION, payload,
            proof: bridgeMac(token, "response", [...transcript, requestPayload, payload]).toString("hex") }) + "\n"
          if (Buffer.byteLength(response) > 8 * 1024 * 1024) { socket.destroy(); return }
          socket.end(response)
        }
        operationTimer = setTimeout(() => socket.destroy(), 25000)
        if (activeOperations >= 16) { reply({ ok: false, kind: "connection", error: "client operation capacity reached" }); return }
        activeOperations++
        const options = { signal: AbortSignal.timeout(20000) }
        try {
          const server = identity(await context.client.server.info(options))
          if (request.server && JSON.stringify(server) !== JSON.stringify(request.server)) {
            reply({ ok: false, kind: "identity", error: "service identity changed" }); return
          }
          let data
          if (request.operation === "info") data = null
          else if (request.operation === "stats") {
            data = await context.client.session.stats({ timezone: "UTC", tools: "none" }, options)
          } else if (request.operation === "statistics-list") {
            if (request.cursor != null && (typeof request.cursor !== "string" || request.cursor.length > 65536)) throw new Error("invalid cursor")
            const page = await context.client.session.list(request.cursor
              ? { limit: 100, cursor: request.cursor } : { limit: 100, order: "asc" }, options)
            data = { ...page, data: page.data.map(metadata) }
          } else if (request.operation === "statistics-messages") {
            if (typeof request.source_id !== "string" || !/^ses_[A-Za-z0-9_]+$/.test(request.source_id)) throw new Error("invalid session")
            if (request.cursor != null && (typeof request.cursor !== "string" || request.cursor.length > 65536)) throw new Error("invalid cursor")
            const page = await context.client.message.list({ sessionID: request.source_id, limit: 200,
              ...(request.cursor ? { cursor: request.cursor } : { order: "asc" }) }, options)
            data = { ...page, data: page.data.map((message) => ({ id: message.id, type: message.type,
              time: { created: message.time.created }, model: message.model, tokens: message.tokens, cost: message.cost })) }
          }
          else if (request.operation === "list") {
            const page = await context.client.session.list(request.cursor
              ? { limit: 100, cursor: request.cursor }
              : { limit: 100, order: "desc", parentID: null }, options)
            data = { ...page, data: page.data.map(metadata) }
          } else if (request.operation === "get" || request.operation === "fork") {
            if (typeof request.source_id !== "string" || !/^ses_[A-Za-z0-9_]+$/.test(request.source_id)) {
              reply({ ok: false, kind: "identity", error: "invalid session identity" }); return
            }
            if (request.operation === "fork") {
              const route = context.ui.router.current()
              if (route.type !== "session" || route.sessionID !== request.source_id) {
                reply({ ok: false, kind: "identity", error: "foreground session changed" }); return
              }
              data = metadata(await context.client.session.fork({ sessionID: request.source_id }, options))
            } else data = metadata(await context.client.session.get({ sessionID: request.source_id }, options))
          } else { reply({ ok: false, kind: "identity", error: "unsupported client operation" }); return }
          reply({ ok: true, server, data })
        } catch (error) {
          reply({ ok: false, kind: error?._tag === "SessionNotFoundError" ? "identity" : "connection", error: request.operation === "fork"
            ? "native fork unconfirmed inspect native history before retry" : "native client request failed" })
        } finally { activeOperations-- }
      }
      socket.on("data", receive)
    })
    const ready = Promise.withResolvers()
    const bridgeReady = ready.promise
    listener.once("error", ready.reject)
    listener.listen(0, "127.0.0.1", () => {
      try {
        const port = listener.address().port
        bridge = { client_id, pane, port, registration }
        writeFileSync(registration, JSON.stringify({ ...bridge, token: token.toString("hex") }), { mode: 0o600, flag: process.platform === "win32" ? "r+" : "wx" })
        ready.resolve()
      } catch (error) { ready.reject(error); listener.close() }
    })
    // Registration is private to the OS user; no nonce enters readouts, argv or logs.
    const environment = Object.fromEntries(["HOME", "USERPROFILE", "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_STATE_HOME", "XDG_CACHE_HOME", "OPENCODE_DB"]
      .filter((key) => process.env[key] !== undefined).map((key) => [key, process.env[key]]))
    let pending = false
    let running = false
    let revision = 0
    let last = ""
    let viewKey = ""
    let view = { foreground_session_id: null, roots: [] }
    const reasons = new Map()
    const rejected = new Set()
    const readView = () => {
      const route = context.ui.router.current()
      const foreground_session_id = route.type === "session" ? route.sessionID : null
      const roots = new Set(context.ui.tabs.list().map((tab) => tab.sessionID))
      if (foreground_session_id) roots.add(foreground_session_id)
      return { foreground_session_id, roots: [...roots].sort() }
    }
    const family = () => new Set(view.roots.flatMap((id) => [id, ...context.data.session.family(id)]))
    const emit = async (snapshot) => {
      const json = JSON.stringify({ snapshot, session_scope })
      if (json === last || closed) return
      await report(snapshot, session_scope)
      last = json
    }
    const refresh = async () => {
      pending = true
      if (running || closed) return
      running = true
      try {
        while (pending && !closed) {
          pending = false
          const generation = revision
          const current = view
          try {
            await bridgeReady
            const server = identity(await context.client.server.info({ signal: AbortSignal.timeout(10000) }))
            session_scope = { environment, opencode: { connection_argv, launch_argv: [], server, bridge } }
            const ids = [...family()]
            const active = await context.client.session.active({ signal: AbortSignal.timeout(10000) })
            const sessions = await Promise.all(ids.map(async (session_id) => {
              const info = await context.client.session.get({ sessionID: session_id }, { signal: AbortSignal.timeout(10000) })
              if (session_id === current.foreground_session_id) session_scope.opencode.session = {
                id: info.id, project_id: info.projectID, created: info.time.created, directory: info.location.directory,
              }
              await Promise.all([
                context.data.session.permission.sync(session_id),
                context.data.session.form.sync(session_id, context.location),
              ])
              const permissions = context.data.session.permission.list(session_id)
              const forms = context.data.session.form.list(session_id, context.location)
              if (!permissions || !forms) throw new Error("pending request snapshot unavailable")
              return {
                session_id, active: Boolean(active[session_id]), outcome: rejected.has(session_id) && info.outcome === "failed" ? "rejected" : info.outcome,
                permissions: permissions.map((request) => request.id),
                forms: forms.filter((form) => form.sessionID === session_id).map((form) => form.id),
                reason: reasons.get(session_id),
              }
            }))
            if (generation !== revision || closed) continue
            await emit({ foreground_session_id: current.foreground_session_id, connection_argv, sessions })
          } catch {
            if (generation !== revision || closed) continue
            // Do not turn a lost transport or partial snapshot into Idle/Done.
            const error = "lyrel: OpenCode presence synchronization failed; server execution outcome is unknown"
            context.ui.toast.show({ message: error, variant: "error" })
            await emit({ foreground_session_id: current.foreground_session_id, connection_argv, sessions: [], error })
          }
        }
      } catch {
        context.ui.toast.show({ message: "lyrel: cannot report OpenCode TUI presence", variant: "error" })
      } finally {
        running = false
      }
    }
    const updateView = () => {
      const next = readView()
      const key = JSON.stringify(next)
      if (key === viewKey) return
      viewKey = key
      view = next
      revision++
      void refresh()
    }
    // A client-owned, non-rendering slot observes route/tabs even without server events.
    const unslot = context.ui.slot({ append: "app", render() {
      createEffect(updateView)
      return undefined
    } })
    const unlisten = context.data.listen(({ details }) => {
      const event = details
      updateView()
      if (event.type === "server.connected") { revision++; void refresh(); return }
      if (![
        "session.execution.started", "session.execution.succeeded", "session.execution.failed",
        "session.execution.interrupted", "permission.asked", "permission.replied",
        "form.created", "form.replied", "form.cancelled", "session.created", "session.updated",
        "session.tool.failed",
      ].includes(event.type)) return
      const id = event.data?.sessionID ?? event.data?.form?.sessionID
      if (!id || !family().has(id)) return
      if (event.type === "session.execution.started") { reasons.delete(id); rejected.delete(id) }
      if (event.type === "permission.replied" && event.data.reply === "reject") {
        rejected.add(id)
        reasons.set(id, "permission rejected")
      }
      if (event.type === "session.execution.interrupted") reasons.set(id, event.data.reason)
      if (event.type === "session.execution.failed") reasons.set(id, "execution failed")
      if (event.type === "session.tool.failed") reasons.set(id, "tool failed; execution continues")
      // Execution, permission and form events all invalidate the authoritative snapshot.
      revision++
      void refresh()
    })
    updateView()
    // Also resynchronize after a lost/recreated connection; never assume live-only replay.
    const timer = setInterval(() => { revision++; void refresh() }, 5000)
    return () => {
      closed = true
      clearInterval(timer)
      listener.close()
      for (const socket of sockets) socket.destroy()
      rmSync(directory, { recursive: true, force: true })
      unlisten()
      unslot()
      // Closing a client is not a successful server execution.
    }
  },
})
